local ui=require("ui");local hw=require("hw");local M={};local sides={"top","bottom","left","right","front","back"}
function M.run(m) while true do ui.clear(m);ui.header(m,"REDSTONE CONTROL");local r=hw.redstone();local w,h=m.getSize();if not r then m.setCursorPos(2,3);m.write("Redstone Integrator not detected.") else local half=math.floor(w/2);for i,s in ipairs(sides) do local c=(i-1)%2;local row=math.floor((i-1)/2);local x=2+c*half;local y=4+row*2;local ok,state=pcall(r.getOutput,s);ui.btn(m,x,y,half-3,s..": "..(ok and state and "ON" or "OFF"),ok and state) end;if h>=13 then ui.btn(m,2,12,half-3,"ALL ON",false);ui.btn(m,2+half,12,half-3,"ALL OFF",false) end end;ui.back(m);local _,x,y=os.pullEvent("monitor_touch");if y==h and x<=10 then return end;if r then for i,s in ipairs(sides) do local c=(i-1)%2;local row=math.floor((i-1)/2);local bx=2+c*math.floor(w/2);local by=4+row*2;if x>=bx and x<bx+math.floor(w/2)-3 and y==by then local ok,state=pcall(r.getOutput,s);pcall(r.setOutput,s,not (ok and state)) end end;if y==12 then if x<2+math.floor(w/2) then for _,s in ipairs(sides) do pcall(r.setOutput,s,true) end else for _,s in ipairs(sides) do pcall(r.setOutput,s,false) end end end end end end
return M
